function ChestPointNodeBehavior:Refresh(parameters)
    self.isLock = parameters.isLock
    self.isSelected = parameters.isSelected
    self.isCurBuy = parameters.isCurBuy
    self.isLast = parameters.isLast
    self:RefreshUI()
