function ChestPointNodeBehavior:RefreshUI()
    self:RefreshImgLineR()
    self:RefreshImgCircle()
    self:RefreshUIFX_SelectGlow()
end

function ChestPointNodeBehavior:RefreshUIFX_SelectGlow()
    KTool.SetActive(self.UIFX_SelectGlow.gameObject, self.isSelected)
end

function ChestPointNodeBehavior:RefreshImgCircle()
    if not self.isLock then
        if self.isSelected then
            self.ImgCircle.Status = 2
        else
            self.ImgCircle.Status = 1
        end
    else
        if self.isCurBuy then
            if self.isSelected then
                self.ImgCircle.Status = 6
            else
                self.ImgCircle.Status = 5
            end
        else
            if self.isSelected then
                self.ImgCircle.Status = 4
            else
                self.ImgCircle.Status = 3
            end
        end
    end
end

function ChestPointNodeBehavior:RefreshImgLineR()
    if self.isLast then
        KTool.SetActive(self.ImgLineR, false)
    end
    if self.isLock then
        self.ImgLineR.Status = 2
    else
        self.ImgLineR.Status = 1
    end
end

